const LOCAL_STORAGE_KEY = "audiodsp_pro_user_presets_v2";
export function loadUserPresets() {
	try {
		const raw = localStorage.getItem(LOCAL_STORAGE_KEY);
		if (!raw) return [];
		const parsed = JSON.parse(raw);
		return Array.isArray(parsed) ? parsed : [];
	} catch (err) {
		console.warn("Failed to load user presets from localStorage", err);
		return [];
	}
}
export function saveUserPresets(presets) {
	try {
		const nonFactory = presets.filter((p) => !p.isFactory);
		localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(nonFactory));
	} catch (err) {
		console.warn("Failed to save user presets to localStorage", err);
	}
}

